   server-side in charity-app-ingest. ?test=1 bypasses it. Manual close is
   data-cc-closed, set by pages_render(data={"closed": true}). */
const OPEN_AT = Date.parse("2026-10-22T05:00:00Z");

const closedBox = document.getElementById("cc-closed");
if (!isTest && (manual || now >= CLOSE_AT || now < OPEN_AT)) {
  form.hidden = true;
