const closedBox = document.getElementById("cc-closed");
const countdown = (target, label) => {
  const boxes = document.querySelectorAll("[data-cd]");
  boxes.forEach((b) => { b.hidden = false; b.querySelector("[data-cd-l]").textContent = label; });
  const pad = (n) => String(n).padStart(2, "0");
  let reloaded = false;
  const tick = () => {
    const left = target - Date.now();
    if (left <= 0) {
      if (!reloaded) { reloaded = true; setTimeout(() => location.reload(), 1500); }
      return;
    }
    const s = Math.floor(left / 1000);
    const u = { d: String(Math.floor(s / 86400)), h: pad(Math.floor(s / 3600) % 24), m: pad(Math.floor(s / 60) % 60), s: pad(s % 60) };
    boxes.forEach((b) => b.querySelectorAll("[data-u]").forEach((el) => {
      const t = u[el.getAttribute("data-u")];
      if (el.textContent !== t) el.textContent = t;
    }));
  };
  tick();
  setInterval(tick, 1000);
};
if (!isTest && (manual || now >= CLOSE_AT || now < OPEN_AT)) {
  form.hidden = true;
  closedBox.hidden = false;
  if (now < OPEN_AT && !manual) {
    status.textContent = "Applications open Monday, Oct 26 · 9 AM CT";
    document.getElementById("cc-bar-t").textContent = "2027 Charity Calendar · opens Mon Oct 26";
    document.getElementById("cc-urg").textContent = "Limited spots · applications open Monday, Oct 26 at 9 AM";
    document.getElementById("cc-closed-h").textContent = "Applications open Monday at 9 AM";
    document.getElementById("cc-closed-p").textContent =
      "Applications open Monday, October 26 at 9 AM Central and close Friday, October 30 at midnight. Set a reminder — spots are limited!";
    countdown(OPEN_AT, "Applications open in");
  } else {
    status.textContent = "Applications are closed";
    document.getElementById("cc-bar-t").textContent = "2027 Charity Calendar · applications closed";
    document.getElementById("cc-urg").textContent = "Applications are closed";
  }
  return;
}
countdown(CLOSE_AT, "Applications close in");
